mapper.select:
SELECT a.sku_id AS skuId, ps.sku_code AS skuCode, COUNT(DISTINCT a.shipment_id) AS shipmentCount, SUM(a.alloc_amount) AS allocAmountCny FROM first_leg_alloc a JOIN first_leg_shipment fl ON a.shipment_id = fl.id AND fl.status IN ('ALLOCATED', 'CLOSED') LEFT JOIN product_sku ps ON a.sku_id = ps.id
AND a.sku_id = #{skuId} AND fl.shipped_at >= #{shippedFrom} AND fl.shipped_at <= #{shippedTo}
GROUP BY a.sku_id, ps.sku_code ORDER BY allocAmountCny DESC, a.sku_id ASC
